<?php
$catalog=\App\LocationService::catalog();
$selected=$values;
$branchName=null;
if(!empty($selected['polling_station_id'])){foreach($catalog['polling_stations'] as $station){if((int)$station['id']===(int)$selected['polling_station_id']){foreach($catalog['electoral_areas'] as $branch){if((int)$branch['id']===(int)$station['electoral_area_id']){$branchName=$branch['name'];break;}}break;}}}
?>
<div class="col-12"><h2 class="h5">Electoral location <span class="small text-secondary fw-normal">Polling station required</span></h2><p class="text-secondary">Choose a region and constituency, then a required polling station. A station can have no branch yet. Its branch updates here when assigned in Locations.</p>
<?php if(empty($values['region_id'])&&array_filter(array_intersect_key($values,array_flip(['region','constituency','electoral_area','polling_station'])))): ?><div class="alert alert-info">Previously saved location: <?= e(implode(' / ',array_filter([$values['region']??null,$values['constituency']??null,$values['electoral_area']??null,$values['polling_station']??null]))) ?>. Select matching directory entries below to link it.</div><?php endif; ?>
<div class="row" data-location-picker data-location-catalog="<?= e(json_encode($catalog,JSON_THROW_ON_ERROR)) ?>">
<?php foreach(['region'=>['Electoral region','regions'],'constituency'=>['Constituency','constituencies'],'polling_station'=>['Polling station','polling_stations']] as $key=>[$title,$table]): ?>
<div class="col-md-6"><label class="form-label" for="location-<?= e($key) ?>"><?= e($title) ?></label><select class="form-select mb-3" name="<?= e($key) ?>_id" id="location-<?= e($key) ?>" data-location="<?= e($key) ?>" <?= $key==='polling_station'?'required aria-required="true"':'' ?>><option value="">Not assigned</option><?php foreach($catalog[$table] as $item): ?><option value="<?= e($item['id']) ?>" <?= (string)($selected[$key.'_id']??'')===(string)$item['id']?'selected':'' ?>><?= e(((string)($item['station_code']??'')!==''?$item['station_code'].' · ':'').(in_array($key,['region','constituency'],true)&&!empty($item['shortname'])?$item['shortname'].' · ':'').$item['name']) ?></option><?php endforeach; ?></select></div>
<?php endforeach; ?><div class="col-md-6 mb-3"><label class="form-label" for="voter-branch-display">Electoral area (branch)</label><input class="form-control" id="voter-branch-display" data-branch-display value="<?= e($branchName??'Branch not assigned') ?>" readonly aria-describedby="voter-branch-help"><p id="voter-branch-help" class="form-text">Assigned automatically from the polling station. Manage station branches in Locations.</p></div></div>
<?php if(\App\Auth::canManage()): ?><p><a href="<?= e(url('locations')) ?>">Manage electoral regions, constituencies, branches and stations</a></p><?php endif; ?></div>
